body.usercss:

#EDITOR_AREA {
    height: 100%;
    width: 100%;
}

.sepoa-editor-wrapper {
    height: 100%;
    width: 100%;
    position: relative;
    display: block;
}

div.sepoaux_component_inner_wrapper.sepoaux_button_inner.sepoaux_wrapper_style_halign_right {
    margin-right: 23px;
}

.container_div {
	border: 1px solid #DDDDDD;
	width : 1140px;
	display: flex;
	flex-direction: column;
	justify-content: center;
}

.lable_div {
	display: flex;
	justify-content: start;
	padding-left: 10px;
	align-items: center;
	height: 40px;
	/*border: 1px solid #DDDDDD;*/
	/*border-radius: 5px;*/
	margin-bottom: 16px;
}

.label_a {
	text-decoration: none; 
	color: inherit;
	line-height: 39px;
	display: block;
	width : 100%;
	height: 100%;
	margin-top: 20px;
}

.label_a:hover {
	 color: blue;
	 font-weight: bold;
}

body.onloadscript:




            switch (name) {
                case "QA_SAVE":
                    doSave();
                    break;
                case "QA_CANCEL":
                    doCancel();
                    break;
                case "APPROVAL_REQ":
                	doApprovalRequest();
                	break;
                default:
                    break;
            }




            if (Sepoa.request.QNA_NUMBER) {
                callFunction('QA_002', 'changeFrame', ['view', Sepoa.request.QNA_NUMBER]);
            } else {
                callFunction('QA_002', 'changeFrame', ['list']);
            }





            new SepoaDhtmlXVaultObject({
                "container": attachContainer.id,
                "mode": null,
                "attach_key": null,
                "callback": attach_callback,
                "type": "QNA",
                "param": "ATTACH_NO"
            });



            vaultObj.setProgressMode("eta");




            tinymce.init({
                selector: "#" + formObj.getContainer("EDITOR_BOX").id,
                theme: "modern",
                height: 350,
                plugins: [
                    "advlist autolink lists link image charmap print preview hr anchor pagebreak",
                    "searchreplace wordcount visualblocks visualchars code fullscreen",
                    "insertdatetime media nonbreaking save table contextmenu directionality",
                    "emoticons template paste textcolor colorpicker textpattern"
                ],
                toolbar1: "styleselect formatselect fontselect fontsizeselect | bold italic underline strikethrough | alignleft aligncenter alignright alignjustify | cut copy paste | searchreplace | bullist numlist | outdent indent blockquote | undo redo | link unlink anchor image code | insertdatetime preview | forecolor backcolor | table | hr removeformat | subscript superscript | charmap emoticons | print fullscreen | ltr rtl | spellchecker | visualchars visualblocks nonbreaking template pagebreak",
                //toolbar2: "undo redo | link unlink anchor image media code | insertdatetime preview | forecolor backcolor | table | hr removeformat | subscript superscript | charmap emoticons | print fullscreen | ltr rtl | spellchecker | visualchars visualblocks nonbreaking template pagebreak",
                paste_data_images: true,
                paste_enable_default_filters: false,
                //paste_word_valid_elements: "p[style],strong/b,em/i,u,span[style],h1,h2,h3,h4,h5,h6,ol,ul,li,a[href],table,thead,tbody,tfoot,tr,td[colspan|rowspan],th[colspan|rowspan],img[src|alt|width|height],br",
				paste_word_valid_elements:"",
                paste_convert_word_fake_lists: false,
                paste_remove_styles_if_webkit: false,
                //paste_retain_style_properties: "color font-size font-family background-color",
                //paste_as_text: false,
                images_upload_handler: function(blobInfo, success, failure) {
                    success("data:" + blobInfo.blob().type + ";base64," + blobInfo.base64());
                },
                statusbar: false,
                file_browser_callback: function(field_name, url, type, win) {
                    tinyImageFileFieldName = field_name;
                    if (type == 'image') $('#tinyFielForm input').click();
                },
                content_css: ['//fonts.googleapis.com/earlyaccess/nanumgothic.css',
                    '//fonts.googleapis.com/earlyaccess/nanummyeongjo.css',
                    '//fonts.googleapis.com/earlyaccess/nanumbrushscript.css',
                    '//fonts.googleapis.com/earlyaccess/nanumpenscript.css',
                    '//cdn.jsdelivr.net/font-nanum/1.0/nanumbarungothic/nanumbarungothic.css'
                ],
                font_formats: 'Andale Mono=andale mono,times;' +
                    'Arial=arial,helvetica,sans-serif;' +
                    'Arial Black=arial black,avant garde;' +
                    'Book Antiqua=book antiqua,palatino;' +
                    'Comic Sans MS=comic sans ms,sans-serif;' +
                    'Courier New=courier new,courier;' +
                    'Georgia=georgia,palatino;' +
                    'Helvetica=helvetica;' +
                    'Impact=impact,chicago;' +
                    'Symbol=symbol;' +
                    'Tahoma=tahoma,arial,helvetica,sans-serif;' +
                    'Terminal=terminal,monaco;' +
                    'Times New Roman=times new roman,times;' +
                    'Trebuchet MS=trebuchet ms,geneva;' +
                    'Verdana=verdana,geneva;' +
                    'Webdings=webdings;' +
                    'Wingdings=wingdings,zapf dingbats;' +
                    '나눔고딕=Nanum Gothic;' +
                    '나눔명조=Nanum Myeongjo;' +
                    /*                     '나눔손글씨 붓체=Nanum Brush Script;' + */
                    '나눔손글씨 펜체=Nanum Pen Script;' +
                    '나눔바른고딕=Nanum Barun Gothic;',
                setup: onInit
            });
            //tinyMCE.activeEditor.setMode("code");
            //tinyMCE.activeEditor.setMode("design");
            formObj.setViewMode(false);
            vaultObj.changeMode('');

            /*if (Sepoa.info.SYSTEM_TYPE == 'CONT') {
                formObj.reloadComboBox('QNA_TYPE', ['SL0024', '{HOUSE_CODE}#{LANGUAGE}#SM024']);
            }*/

body.userscript:

            //폼초기화


            //조회


            //저장


            (function(window) {
                window.htmlentities = {
                    encode: function(str) {
                        var buf = [];

                        for (var i = str.length - 1; i >= 0; i--) {
                            buf.unshift(['&#', str[i].charCodeAt(), ';'].join(''));
                        }

                        return buf.join('');
                    },
                    decode: function(str) {
                        return str.replace(/&#(\d+);/g, function(match, dec) {
                            return String.fromCharCode(dec);
                        });
                    }
                };
            })(window);



            dataOutput.setValue("ATTACH_NO", e.attach_key);




            formObj.clear();




        	let arr = JSON.parse(dataOutput.getValue("JOIN_STRING"));

        	for(let i in arr){
        		if(arr[i].qnaNumber == e.target.dataset.key){
        			arr.splice(i,1);
        			e.target.parentElement.parentElement.remove()
        			break;
        		}
        	}

        	dataOutput.setValue("JOIN_STRING", JSON.stringify(arr));




            clearForm();
            var so = doServiceAjax('sepoa.svc.board.SepoaQAService', 'CONNECTION', 'getDetail', {
                QNA_NUMBER: qnaNumber
            }, function(so) {
                if (so.status == 1) {
   					let detailObjStr = so.result[0];
					let detailObj = JSON.parse(detailObjStr);
					let qnaNumberArr = [];

                    if (detailObj) {
						let qnaDetail = detailObj["QNA_DETAIL"];
						let qnaLink = detailObj["QNA_LINK"];

						let labelstr = "";
						let linkBannerHeight = 1;
						if(qnaLink && qnaLink["CONTENT"] != "") {
							let linkArray = JSON.parse(qnaLink["CONTENT"]);

							for(let linkEl of linkArray) {
								let qnaNumberSubjectObj = {};

								let qnaNumber = linkEl.qnaNumber;
						 		let subject = linkEl.subject;
						 		let url = document.location.origin + '/link.sux?ln=79bde217-722b-4144-97f9-1ac7f7d36979&QNA_NUMBER=' + qnaNumber;
						 		labelstr += "<div class=\"container_div\"><div class=\"lable_div\"><a class=\"label_a\" href=\"javascript:void(0);\" onclick=\"window.open('"+url+"','popup','width=1200,height=1000')\">"+subject+"</a><div class=\"label_a delete_btn\" data-key=\"" + qnaNumber + "\" style=\"width:50px; cursor:pointer;\">삭제</div></div></div>";

						 		qnaNumberSubjectObj.qnaNumber = qnaNumber;
								qnaNumberSubjectObj.subject = subject;
								qnaNumberArr.push(qnaNumberSubjectObj);

						 		linkBannerHeight++;
							}
						} 

						formObj.getForm(Object.keys(formObj._formList)[0]).addItem("REF_LINK",{
						    "type": "block",
						    "width": "auto",
						    "blockOffset": "",
						    "name": "customBlock",
						    "list":[{
							    "type": "label",
						        "label": labelstr,
						        "name": "REF_DOC_LINK",
						        "labelWidth": "200",
						        "labelHeight": (60*linkBannerHeight).toString()
							}]
						});

	                    dataOutput.setValue("JOIN_STRING", JSON.stringify(qnaNumberArr));
                        setData(qnaDetail);
                    }


                    dataOutput.setValue('QNA_NUMBER', qnaNumber);
                    dataOutput.setValue('mode', 'EDIT');
                } else {
                    Alert(so.message);
                }
            });




        	doSave({functionName : doSetApproval});




        	let applyTypePrefix = "QNA_";
        	let applyTypePostFix = Sepoa.request["cntrType"] == "C" ? "C" :"D";
        	let paramsObj = {
        		QNA_NUMBER: dataOutput.getValue("QNA_NUMBER"),
        		APPLY_TYPE: applyTypePrefix + applyTypePostFix
        	}

           doServiceAjax('sepoa.svc.approval.SepoaGWApprovalService', 'TRANSACTION', 'sendApproval', paramsObj, function(so) {
		    	if (so.status == 1) {
				    var width = Math.min(SUX.root.innerWidth * 0.7, 1280);
				    var height = Math.min((SUX.root.innerHeight - 100) * 0.9, 800);
					PopupOpenPostReal(so.result[0], width, height, dataOutput.getValue("QNA_NUMBER"), JSON.parse(so.result[1]));
					var win = sUtils.popup.getWindowObject(dataOutput.getValue("QNA_NUMBER"));

					setTimeout(function run() {
						if(win.closed) {
						    doCancel();
						} else {
							setTimeout(run, 500);
						}
					}, 500);
				} else {
					Alert(so.message);
				}
			});




        	var params = {};
            params.data = [{
                SEAL_SORT: 'U',
                APP_LINE_SEQ: '0',
                APP_METHOD: '01',
                APP_USER_ID: Sepoa.info.ID,
                APP_USER_NAME: Sepoa.info.NAME_LOC,
                SELLER_CODE: Sepoa.info.COMPANY_CODE,
                POSITION: Sepoa.info.POSITION,
                DEPARTMENT_NAME: Sepoa.info.DEPARTMENT_NAME_LOC,
                EMPLOYEE_NO: Sepoa.info.EMPLOYEE_NO
            }];

            var width = Math.min(SUX.root.innerWidth * 0.7, 1280);
            var height = Math.min((SUX.root.innerHeight - 100) * 0.9, 800);
            PopupOpenPost('/UxDefault/ApprovalLine/Popup.sux', params, function(data) {
                var params = {};
                params.data = data;
                doApprovalProcess(data);
            }, width, height, Sepoa.cache.text.get('SLM_221.APPLINE_SETTING'));




        	let appObj = {
        	 	APP_LINE : data.approver,
        		APP_INFO : {
        			APP_COMMENT : data.comment
        		}, 
        		REQ_SEAL_INFO : {
        			SUBJECT: formObj.getValue("SUBJECT")
        		}
        	};

        	doServiceAjax('sepoa.svc.board.SepoaQAService', 'TRANSACTION', 'doRequestApproval', {PARAMETER: JSON.stringify(appObj), QNA_NUMBER: dataOutput.getValue("QNA_NUMBER")}, function(so) {
				if(so.status == 1) {
					if (so.status == 1) {
						Alert(Sepoa.cache.text.get('MESSAGE.0054'));
                           	callFunction('QA_002', 'changeFrame', ['list']);
					} else {
						Alert("결재 상신중 에러가 발생하였습니다. <br/> 다시 시도해주세요.")
					}
				}
        	});




            var cntrType = Sepoa.request["cntrType"];

            if (!formObj.validate()) {
                Alert(Sepoa.cache.text.get('MESSAGE.0002'));
                return;
            }
            let contents = tinyMCE.activeEditor.getContent();
            if(noticeEncOption === "on"){
                //contents = sUtils.string.getSecureString(sUtils.string.decodeHTML(contents))??"";
            }

            dataOutput.setValue("CONTENT", contents);
            dataOutput.setValue("CNTR_TYPE", cntrType);
            if (Confirm(Sepoa.cache.text.get('MESSAGE.1018'), function(result) {
                    if (result) {
                        var so = doServiceAjax('sepoa.svc.board.SepoaQAService', 'TRANSACTION', 'doSave', null, function(so) {
                            if (so.status == 1) {
                            	if(callback && callback.functionName) {
                            		let qnaNumber = so.result[0];
                            		if(qnaNumber && dataOutput.getValue("QNA_NUMBER") =="") {
                            			dataOutput.setValue("QNA_NUMBER", qnaNumber);
                            			dataOutput.setValue('mode', 'EDIT');
                            		}

                            		callback.functionName();
                            	} else {
                            		Alert(Sepoa.cache.text.get('MESSAGE.0054'));
                                	callFunction('QA_002', 'changeFrame', ['list']);
                            	}
                            } else {
                                Alert(so.message);
                            }
                        });
                    }
                }));




            ed.on('init', function(args) {
                if (Sepoa.request.QNA_NUMBER) {
                    doQuery(Sepoa.request.QNA_NUMBER);
                } else {
                    if (Sepoa.request.cntrType != 'C') {
                        // 동아제약 커스텀문구 추가
                        // C를 계약용으로 설계했으나 운영시스템에서 추가된 게시판을 일반게시판으로 사용하겠다고함.
                        // cntrType == C ==> 일반게시판 , 아닐경우 계약용
                        var customText = '';
                        customText += '※ 계약서 검토 요청시 필수 기재 항목안내. 누락시 검토진행 불가 <br>';
                        customText += '<div style="margin-left: 10px;">1. 계약회사</div>';
                        customText += '<div style="margin-left: 10px;">2. 계약국가</div>';
                        customText += '<div style="margin-left: 10px;">3. 계약체결일(예정)</div>';
                        customText += '<div style="margin-left: 10px;">4. 계약내용</div>';
                        tinyMCE.activeEditor.setContent(customText);
                    }
                }
            });




            var c = '';
            if (qnaDetail.CONTENT != undefined) {
                c = qnaDetail.CONTENT.replaceAll("\\\"", "\"");
            }

            clearForm();
            formObj.dataMapper(qnaDetail, "JSON");
            tinyMCE.activeEditor.setContent(c);

			vaultObj.setAttachKey(qnaDetail['ATTACH_NO']);
            dataOutput.setValue("QNA_NUMBER", qnaDetail['QNA_NUMBER']);
            dataOutput.setValue("REPLY_CNT", qnaDetail['REPLY_CNT']);
            dataOutput.setValue("WRITER_ID", qnaDetail['ADD_USER_ID']);




            var target = formObj.getContainer("EDITOR_BOX");
            var height = document.body.offsetHeight - dhx.absTop(formObj.getContainer("EDITOR_BOX")) - 80;
            target.style.height = height + 'px';
            target.style.border = 'solid 1px rgba(0,0,0,0.2)';

            formObj._parent.addEventListener('click', (e) => {
            	if(e.target.classList.contains('delete_btn')) {
				    removeLink(e);
				}
            })





            tinymceReady = true;
            if (tinymceContent != '') {
                tinyMCE.activeEditor.setContent(tinymceContent);
            }

            if (formObj.getValue('NOTICE_NUMBER') != '') {
                changeMode('view');
            } else {
                changeMode('insert');
            }
            editorResize();




            var f = tinyMCE.activeEditor.iframeElement;
            tinyMCE.activeEditor.iframeElement.style.height = $('.sepoa-editor-wrapper')[0].offsetHeight - f.offsetTop - 5 + "px"




            btnObj.showButton(null, false)
            if (mode == 'view') {
                tinyMCE.activeEditor.setMode("readonly")
                formObj.setViewMode(true);
                formObj.showItem('NOTICE_NUMBER');
                btnObj.showButton('add,update,delete', true)
            } else {
                tinyMCE.activeEditor.setMode("code");
                formObj.setViewMode(false);
                formObj.hideItem('NOTICE_NUMBER');
                btnObj.showButton('save,cancel', true)
            }




        	debugger;
        	// 팝업 오픈
        	let popupUrl = window.CONTEXT_NAME + '/Seal/Board/Qna/BoardQnaList.sux';
        	if(Sepoa.request && Sepoa.request.cntrType) {
        		if(Sepoa.request.cntrType == "C") {
        			popupUrl += "?cntrType=C";
        		}
        	}

        	if (name == "REF_LINK") {
				sUtils.popup.modal({
					url: popupUrl,
					params: {
						callback: function(params) {
						 	let labelstr = "";
						 	let qnaNumberArr = [];
						 	let qnaNumberSubjectObj = {};		

							formObj.getForm(Object.keys(formObj._formList)[0]).removeItem("customBlock"); // 폼 블럭 초기화

							for(let i = 0 ; i < params.length ; i++) {
							 	const addr = params[i].addr;
					 			const subject = params[i].subject;
								const qnaNumber = addr.slice(addr.lastIndexOf("=") + 1);

								labelstr += "<div class=\"container_div\"><div class=\"lable_div\"><a class=\"label_a\" href=\"javascript:void(0);\" onclick=\"window.open('"+addr+"','popup','width=1200,height=1000')\">"+subject+"</a><div class=\"label_a delete_btn\" data-key=\"" + qnaNumber + "\" style=\"width:50px; cursor:pointer;\">삭제</div></div></div>";


								qnaNumberSubjectObj.qnaNumber = qnaNumber;
								qnaNumberSubjectObj.subject = subject;

								qnaNumberArr.push(Object.assign({}, qnaNumberSubjectObj));
							}

							formObj.getForm(Object.keys(formObj._formList)[0]).addItem("REF_LINK",{
							    "type": "block",
							    "width": "auto",
							    "blockOffset": "",
							    "name": "customBlock",
							    "list":[{
								    "type": "label",
							        "label": labelstr,
							        "name": "REF_DOC_LINK",
							        "labelWidth": "200",
							        "labelHeight": (60*params.length).toString()
								}]
							});

							dataOutput.setValue("JOIN_STRING", JSON.stringify(qnaNumberArr));
	       				}
					},
					title: Sepoa.cache.text.get('QA_002_2.POPUP_SUBJECT')
				});
        	}
